static void seError(bool OK,xcronexecutorissue* I,xcronexecutorerror Expected,cstr Text)
{testRequire(!OK && I->Code==Expected && xrtErrorCode(xrtGetError())==(int32)Expected && !strcmp(xrtErrorDomain(xrtGetError()),"xrt.cron.executor"),Text);xrtClearError();}
static void seBlock(ptr Raw)
{selectedexeccontext* C=Raw;xrtAtomic32Store(&C->Started,1,XMEMORY_RELEASE);seWait(&C->Gate,1,"external selected pool blocker released");}
static void testSEQueueAndTail(void)
{
    xexecutor* E=sePool(1,1);selectedexeccontext Block={0},C={.ProbeNotify=true};testRequire(xrtExecutorSubmit(E,seBlock,&Block,NULL,NULL),"selected pool blocker");seWait(&Block.Started,1,"selected pool blocked");xcronexecutor* B=seAdapter(E,2,&C,true);xcronselectedrun R=seLease(1,7),Other=seLease(2,8);xcronexecutorissue I;
    testRequire(xcronExecutorSubmitSelected(B,&R,NULL),"selected queued admission");seError(xcronExecutorSubmitSelected(B,&R,&I),&I,XCRON_EXECUTOR_DUPLICATE,"selected active duplicate");seError(xcronExecutorSubmitSelected(B,&Other,&I),&I,XCRON_EXECUTOR_REJECTED,"selected queue rejection transfers nothing");testRequire(I.Cause==XERR_AGAIN,"selected queue rejection cause retained");
    xallocationbudget* Budget=NULL;xallocationscope Scope={0};testRequire(xrtAllocationBudgetCreate(1,&Budget) && xrtAllocationBudgetEnter(Budget,&Scope),"selected rejection OOM quota");testRequire(!xcronExecutorSubmitSelected(B,&Other,&I) && I.Code==XCRON_EXECUTOR_REJECTED && I.Cause==XERR_AGAIN && xrtErrorKind(xrtGetError())==XERR_MEMORY,"selected rejection duty/typed cause survive diagnostic OOM");testRequire(xrtAllocationBudgetLeave(&Scope),"leave selected rejection quota");xrtClearError();xrtAllocationBudgetFree(Budget);
    testRequire(xcronExecutorCancel(B,R.Run.Id,NULL) && xcronExecutorCancel(B,R.Run.Id,NULL),"selected queued token cancellation");uint32 Requested=99;testRequire(xcronExecutorCancelJob(B,R.Run.Job,&Requested,NULL) && Requested==0,"selected job cancellation counts newly requested tokens only");testRequire(xrtExecutorCancel(E),"native queued cancellation publishes selected metadata without Proc");
    xcronselectedcompletion D=seReceipt(B);seSame(&D.Run,&R);testRequire(D.Result==XCRON_RUN_CANCELLED && D.Code==XCRON_EXECUTOR_OK && !D.Error && !xrtAtomic64Load(&C.Calls,XMEMORY_RELAXED) && xrtAtomic32Load(&C.Reentry,XMEMORY_ACQUIRE)==1,"native selected drop skips Proc, preserves metadata and rejects owner reentry");xrtAtomic32Store(&Block.Gate,1,XMEMORY_RELEASE);seEnd(B);sePoolEnd(E);
    E=sePool(1,4);C=(selectedexeccontext){.BlockNotify=true};B=seAdapter(E,1,&C,true);R=seLease(17,9);testRequire(xcronExecutorSubmitSelected(B,&R,NULL),"selected blocked-notify submission");seWait(&C.NotifyEntered,1,"selected Notify tail entered");D=seReceipt(B);seSame(&D.Run,&R);xcronexecutorstats S;testRequire(xcronExecutorInspect(B,&S,NULL) && !S.Active && S.Producers==1,"selected physical receipt independent of Notify tail");seError(xcronExecutorDestroy(B,&I),&I,XCRON_EXECUTOR_BUSY,"selected tail still borrows adapter");
    Other=seLease(258,10);testRequire(xcronExecutorSubmitSelected(B,&Other,NULL),"reuse selected label slot before old Notify exits");memset(&R,0x5a,sizeof(R));xrtAtomic32Store(&C.NotifyGate,1,XMEMORY_RELEASE);D=seReceipt(B);seSame(&D.Run,&Other);testRequire(D.Result==XCRON_RUN_SUCCEEDED && !D.Error,"reused selected view belongs to the new run");seEnd(B);sePoolEnd(E);
}
typedef struct seownerfixture {xexecutor* Pool;selectedexeccontext Callback;xatomic32 Finished;} seownerfixture;
static void seOwnerCreate(ptr Raw)
{seownerfixture* F=Raw;xcronexecutor* B=seAdapter(F->Pool,1,&F->Callback,true);xcronselectedrun R=seLease(1,1);testRequire(xcronExecutorSubmitSelected(B,&R,NULL),"selected worker-owned submission");}
static void seOwnerFinish(ptr Raw)
{seownerfixture* F=Raw;xcronselectedcompletion D=seReceipt(F->Callback.Adapter);xcronselectedrun R=seLease(1,1);seSame(&D.Run,&R);testRequire(D.Result==XCRON_RUN_FAILED && D.Code==XCRON_EXECUTOR_OWNER_CONFLICT && !D.Error && !xrtAtomic64Load(&F->Callback.Calls,XMEMORY_RELAXED),"selected callback is refused on adapter owner thread with metadata retained");seEnd(F->Callback.Adapter);xrtAtomic32Store(&F->Finished,1,XMEMORY_RELEASE);}
static void testSEOwnerAndStress(void)
{
    seownerfixture F={.Pool=sePool(1,4)};testRequire(xrtExecutorSubmit(F.Pool,seOwnerCreate,&F,NULL,NULL),"selected owner fixture created on real worker");seWait(&F.Callback.Notified,1,"selected owner-conflict receipt published");xcronexecutorissue I;xcronexecutorstats S;seError(xcronExecutorInspect(F.Callback.Adapter,&S,&I),&I,XCRON_EXECUTOR_THREAD,"foreign selected controller rejected");testRequire(xrtExecutorSubmit(F.Pool,seOwnerFinish,&F,NULL,NULL),"selected completion returns to actual owner");seWait(&F.Finished,1,"selected worker-owned adapter released");sePoolEnd(F.Pool);
    xexecutor* E=sePool(4,128);selectedexeccontext C={.Mode=3};xcronexecutor* B=seAdapter(E,64,&C,false);uint64 Total=0;
    for(unsigned Round=0;Round<256;++Round){xcronselectedrun R[64];bool Seen[64]={false};for(unsigned J=0;J<64;++J){R[J]=seLease((uint64)Round*64+J+1,1+J%7);R[J].Run.Data=&R[J];testRequire(xcronExecutorSubmitSelected(B,&R[J],NULL),"selected concurrent bounded admission");}
        for(unsigned J=0;J<64;J+=3)testRequire(xcronExecutorCancel(B,R[J].Run.Id,NULL),"selected concurrent cancellation");
        unsigned Received=0;double Deadline=xrtTimer()+10;
        while(Received<64){xcronselectedcompletion D[7];size_t N;testRequire(xcronExecutorDrainSelected(B,D,1+Round%7,&N,NULL),"selected bounded concurrent drain");if(!N){testRequire(xrtTimer()<Deadline,"selected concurrent receipt deadline");xrtThreadYield();}
            for(size_t J=0;J<N;++J){uint64 Index=D[J].Run.Run.Id-(uint64)Round*64-1;testRequire(Index<64 && !Seen[Index],"selected exactly-once concurrent receipt IDs");seSame(&D[J].Run,&R[Index]);testRequire(D[J].Code==XCRON_EXECUTOR_OK && !D[J].Error && (D[J].Result==XCRON_RUN_SUCCEEDED || D[J].Result==XCRON_RUN_CANCELLED),"selected concurrent result/cancellation metadata");Seen[Index]=true;++Received;++Total;}
        }
    }
    testRequire(Total==16384 && xcronExecutorInspect(B,&S,NULL) && S.Submitted==Total && S.Drained==Total && !S.Active && S.Peak<=64,"selected concurrent accounting and hash/label reuse");seEnd(B);sePoolEnd(E);
}
static void testSEKernelAndLimits(void)
{
    xexecutor* E=sePool(2,8);selectedexeccontext C={.Block=true,.Mode=3,.Real=true};xcronexecutor* B=seAdapter(E,2,&C,false);xcronzone* Z=NULL;xcronscheduler* K=NULL;xcronschedulerconfig SC={1,2,64,0,65536};xcronjobconfig J={.Overlap=XCRON_OVERLAP_ALLOW,.RunningLimit=2};
    testRequire(xcronZoneCreatePosix(XRT_STR_LITERAL("EST5EDT,M3.2.0,M11.1.0"),XCRON_ZONE_TZIF3,&Z,NULL) && xcronExpressionCompile(XRT_STR_LITERAL("0 30 1 * * *"),XCRON_SECONDS6,&J.Expression,NULL) && xrtDateTime(2024,11,3,5,30,0,0,&J.Begin) && xcronSchedulerCreateSelected(&SC,&K,NULL),"actual selected kernel/adapter fixture");J.End=J.Begin+XRT_TIME_HOUR;J.Zone=Z;int* Data=xrtMalloc(sizeof(*Data));testRequire(Data!=NULL,"selected owned job data");*Data=42;J.Data=Data;xcronjobid Id;testRequire(xcronSchedulerAddSelected(K,&J,(xcrondeliverypolicy){0,1},&Id,NULL),"actual selected job admission");xcronZoneRelease(Z);
    xcronselectedrun Runs[2];size_t Count=0;for(unsigned T=0;T<128 && Count<2;++T){xcronselectedpoll P;testRequire(xcronSchedulerPollSelected(K,(xcronclock){J.End,T},(xcronoccurrencebudget){1,1,1,1,1},Runs+Count,2-Count,&P,NULL),"actual selected lease progression");Count+=P.Poll.Count;}
    testRequire(Count==2 && Runs[0].Candidates==2 && Runs[1].Candidates==2 && !memcmp(&Runs[0].Local,&Runs[1].Local,sizeof(Runs[0].Local)),"actual repeated label produces both complete global snapshots");C.Expected=(xcronexecutionlabel){Runs[0].Local,2};for(unsigned N=0;N<2;++N)testRequire(xcronExecutorSubmitSelected(B,&Runs[N],NULL),"selected kernel lease reaches real worker");seWait(&C.Started,2,"both selected callbacks running");memset(Runs,0x5a,sizeof(Runs));testRequire(xcronSchedulerClose(K,NULL),"close selected scheduler with active data");uint32 Requested;testRequire(xcronExecutorCancelJob(B,Id,&Requested,NULL) && Requested==2,"selected physical tokens requested after job close");xcronselectedretired R;bool Found=true;testRequire(xcronSchedulerReapSelected(K,&R,&Found,NULL) && !Found && *Data==42,"selected Data lives through both worker bodies");xrtAtomic32Store(&C.Gate,1,XMEMORY_RELEASE);
    for(unsigned N=0;N<2;++N){xcronselectedcompletion D=seReceipt(B);testRequire(D.Result==XCRON_RUN_CANCELLED && D.Run.Candidates==2 && D.Run.Local.Hour==1 && D.Run.Local.Minute==30 && !D.Error && xcronSchedulerComplete(K,D.Run.Run.Id,D.Result,NULL),"actual physical selected completion returns full repeated label");}
    testRequire(xcronSchedulerReapSelected(K,&R,&Found,NULL) && Found && R.Data==Data && R.Info.Cancelled==2 && !R.Info.Running,"actual selected retirement after both physical bodies");xrtFree(Data);testRequire(xcronSchedulerDestroy(K,NULL),"selected kernel drained");seEnd(B);sePoolEnd(E);
    E=sePool(1,4);C=(selectedexeccontext){0};B=seAdapter(E,1,&C,false);xcronexecutorstats Stats;testRequire(xcronExecutorInspect(B,&Stats,NULL),"selected exact bytes");xcronexecutorconfig Config={E,seProc,&C,NULL,NULL,1,0,Stats.Bytes-1};xcronexecutor* Out=B;xcronexecutorissue I;
    seError(xcronExecutorCreateSelected(&Config,&Out,&I),&I,XCRON_EXECUTOR_LIMIT,"selected full arena respects byte limit");testRequire(Out==B,"selected factory failure preserves output");Config.BytesLimit=Stats.Bytes;testRequire(xcronExecutorCreateSelected(&Config,&Out,NULL),"selected exact byte limit accepted");seEnd(Out);
    xcronselectedrun Run=seLease(1,1),Bad=Run;Bad.Candidates=0;memset(&I,0x5a,sizeof(I));xcronexecutorissue Previous=I;
    testRequire(!xcronExecutorSubmitSelected(B,&Bad,&I) && !memcmp(&I,&Previous,sizeof(I)),"bad selected metadata rejected atomically");xrtClearError();testRequire(!xcronExecutorSubmit(B,&Run.Run,&I) && !memcmp(&I,&Previous,sizeof(I)),"plain submit cannot omit selected metadata");xrtClearError();
    xcronselectedcompletion Done;size_t N=77;testRequire(!xcronExecutorDrainSelected(B,&Done,1,(size_t*)&Done,&I) && !memcmp(&I,&Previous,sizeof(I)),"selected output aliases preserve all outputs");xrtClearError();testRequire(!xcronExecutorDrainSelected(B,(xcronselectedcompletion*)B,1,&N,&I) && N==77,"selected metadata array is inside owner alias bounds");xrtClearError();testRequire(!xcronExecutorDrainSelected(B,&Done,SIZE_MAX,&N,&I) && N==77,"selected drain overflow rejected");xrtClearError();xcroncompletion Plain;testRequire(!xcronExecutorDrain(B,&Plain,1,&N,&I) && N==77,"plain drain cannot truncate selected receipts");xrtClearError();
    xallocationbudget* Budget=NULL;xallocationscope Scope={0};testRequire(xrtAllocationBudgetCreate(1,&Budget) && xrtAllocationBudgetEnter(Budget,&Scope),"selected factory OOM quota");Out=NULL;testRequire(!xcronExecutorCreateSelected(&Config,&Out,&I) && !Out && I.Code==XCRON_EXECUTOR_MEMORY && xrtErrorKind(xrtGetError())==XERR_MEMORY,"selected factory typed OOM");testRequire(xrtAllocationBudgetLeave(&Scope),"leave selected factory quota");xrtClearError();xrtAllocationBudgetFree(Budget);
    testRequire(xcronExecutorSubmitSelected(B,&Run,NULL),"warm selected runtime caches");Done=seReceipt(B);testRequire(xrtAllocationBudgetCreate(1,&Budget),"warm selected owner quota");xrtSetErrorInfo(XERR_STATE,"selected.warm.owner",17,"preserve owner");const xerror* Ambient=xrtGetError();testRequire(xrtAllocationBudgetEnter(Budget,&Scope),"selected warm quota entered");
#if defined(XRT_FEATURE_MEMORY_STATS)
    xmemstats Before,After;xrtMemStatsEnable(true);xrtMemStatsGet(&Before);
#endif
    for(unsigned T=0;T<4096;++T){Run=seLease(T+2,1);testRequire(xcronExecutorSubmitSelected(B,&Run,NULL),"selected no-heap submission");Done=seReceipt(B);seSame(&Done.Run,&Run);testRequire(Done.Result==XCRON_RUN_SUCCEEDED && !Done.Error && xrtGetError()==Ambient,"selected no-heap result/error identity");}
#if defined(XRT_FEATURE_MEMORY_STATS)
    xrtMemStatsGet(&After);xrtMemStatsEnable(false);testRequire(Before.MallocCalls==After.MallocCalls && Before.CallocCalls==After.CallocCalls && Before.ReallocCalls==After.ReallocCalls && Before.BlockAllocCalls==After.BlockAllocCalls,"selected adapter/view/receipt and warmed pool request no heap");
#endif
    testRequire(!Scope.Rejections && xrtAllocationBudgetLeave(&Scope),"selected warm quota rejected nothing");xrtClearError();xrtAllocationBudgetFree(Budget);testRequire(xcronExecutorClose(B,true,NULL) && xcronExecutorClose(B,true,NULL),"selected close is idempotent");seError(xcronExecutorSubmitSelected(B,&Run,&I),&I,XCRON_EXECUTOR_CLOSED,"selected close rejects new submissions");seEnd(B);sePoolEnd(E);
}
static void seBatchReceipts(xcronexecutor* B,const xcronselectedrun* Expected,size_t Count,bool Cancelled)
{
    uint64 Seen=0;
    for(size_t I=0;I<Count;++I){xcronselectedcompletion D=seReceipt(B);uint64 J=D.Run.Run.Id-Expected[0].Run.Id;
        testRequire(J<Count && !(Seen&(UINT64_C(1)<<J)),"selected batch returns every ID exactly once");Seen|=UINT64_C(1)<<J;seSame(&D.Run,&Expected[J]);testRequire(D.Result==(Cancelled?XCRON_RUN_CANCELLED:XCRON_RUN_SUCCEEDED) && D.Code==XCRON_EXECUTOR_OK && !D.Error,"selected batch per-lease result and metadata");}
}
static int32 seBatchForeign(ptr Raw)
{selectedexeccontext* C=Raw;xcronselectedrun R=seLease(1,1);xcronexecutorissue I;seError(xcronExecutorSubmitBatchSelected(C->Adapter,&R,1,&I),&I,XCRON_EXECUTOR_THREAD,"foreign selected batch controller rejected");return 0;}
static void testSEBatches(void)
{
    xexecutor* E=sePool(4,128);selectedexeccontext C={0};xcronexecutor* B=seAdapter(E,64,&C,false);xcronexecutorissue I;xcronexecutorstats S;xcronselectedrun Runs[64],Bad[64];
    for(unsigned J=0;J<64;++J)Runs[J]=seLease(J+1,7);
    memset(&I,0x5a,sizeof(I));xcronexecutorissue Previous=I;testRequire(!xcronExecutorSubmitBatchSelected(B,Runs,0,&I) && !xcronExecutorSubmitBatchSelected(B,Runs,65,&I) && !memcmp(&I,&Previous,sizeof(I)),"selected batch count arguments preserve outputs");xrtClearError();
    testRequire(!xcronExecutorSubmitBatchSelected(B,(const xcronselectedrun*)B,1,&I) && !xcronExecutorSubmitBatchSelected(B,Runs,2,(xcronexecutorissue*)Runs) && !memcmp(&I,&Previous,sizeof(I)),"selected batch owned/input/output aliases preserve outputs");xrtClearError();
    memcpy(Bad,Runs,sizeof(Runs));Bad[63].Candidates=0;testRequire(!xcronExecutorSubmitBatchSelected(B,Bad,64,&I) && !memcmp(&I,&Previous,sizeof(I)),"selected invalid final nominal field rejects whole batch");xrtClearError();
    testRequire(!xcronExecutorSubmitBatch(B,&Runs[0].Run,1,&I) && !memcmp(&I,&Previous,sizeof(I)),"plain batch cannot truncate selected metadata");xrtClearError();
    xthread* Foreign=xrtThreadCreate(seBatchForeign,&C,0);testRequire(Foreign && xrtThreadWaitFor(Foreign,10000)==XWAIT_OK,"foreign selected batch controller joined");xrtThreadDestroy(Foreign);
    for(unsigned Position=1;Position<64;++Position){memcpy(Bad,Runs,sizeof(Runs));Bad[Position]=Runs[0];seError(xcronExecutorSubmitBatchSelected(B,Bad,64,&I),&I,XCRON_EXECUTOR_DUPLICATE,"every selected duplicate prefix rolls back");
        testRequire(xcronExecutorInspect(B,&S,NULL) && !S.Active && !S.Producers && xcronExecutorSubmitBatchSelected(B,Runs,64,NULL),"selected maximum capacity/IDs reused after rollback");seBatchReceipts(B,Runs,64,false);}
    xcronexecutorconfig PlainConfig={E,seProc,&C,NULL,NULL,1,0,SIZE_MAX};xcronexecutor* Plain=NULL;testRequire(xcronExecutorCreate(&PlainConfig,&Plain,NULL),"plain batch mode fixture");testRequire(!xcronExecutorSubmitBatchSelected(Plain,Runs,1,&I),"selected batch rejected on plain mode");xrtClearError();seEnd(Plain);seEnd(B);sePoolEnd(E);

    E=sePool(4,128);C=(selectedexeccontext){.Block=true,.Mode=3};B=seAdapter(E,64,&C,true);memcpy(Bad,Runs,sizeof(Runs));testRequire(xcronExecutorSubmitBatchSelected(B,Runs,64,NULL),"selected full immutable batch admitted atomically");seWait(&C.Started,4,"four selected batch callbacks active");memset(Runs,0xa5,sizeof(Runs));
    uint32 Requested;testRequire(xcronExecutorCancelJob(B,7,&Requested,NULL) && Requested==64 && xrtExecutorCancel(E) && xcronExecutorClose(B,true,NULL),"selected job tokens/native queued cancel/close retain all batch duties");seError(xcronExecutorDestroy(B,&I),&I,XCRON_EXECUTOR_BUSY,"active batch cannot destroy immutable labels");xrtAtomic32Store(&C.Gate,1,XMEMORY_RELEASE);seBatchReceipts(B,Bad,64,true);seEnd(B);sePoolEnd(E);memcpy(Runs,Bad,sizeof(Runs));

    E=sePool(4,4);C=(selectedexeccontext){0};B=seAdapter(E,64,&C,false);seError(xcronExecutorSubmitBatchSelected(B,Runs,6,&I),&I,XCRON_EXECUTOR_REJECTED,"selected atomic native batch exceeds one queue despite aggregate space");testRequire(I.Cause==XERR_AGAIN && !xrtAtomic64Load(&C.Calls,XMEMORY_ACQUIRE) && xcronExecutorInspect(B,&S,NULL) && !S.Active && !S.Producers,"selected native rejection publishes no prefix");
    testRequire(xcronExecutorSubmitBatchSelected(B,Runs,4,NULL),"selected native-rejected labels and IDs reusable");seBatchReceipts(B,Runs,4,false);seEnd(B);sePoolEnd(E);

    E=sePool(2,8);C=(selectedexeccontext){.BlockNotify=true};B=seAdapter(E,2,&C,true);testRequire(xcronExecutorSubmitBatchSelected(B,Runs,2,NULL),"old selected batch publication-tail fixture");seWait(&C.Notified,2,"both old batch Notify tails blocked");seBatchReceipts(B,Runs,2,false);
    testRequire(xcronExecutorInspect(B,&S,NULL) && !S.Active && S.Producers==2,"old batch tails live independently from drained receipts");seError(xcronExecutorDestroy(B,&I),&I,XCRON_EXECUTOR_BUSY,"both old batch publication tails protect adapter");
    xcronselectedrun Reuse[2]={seLease(100,7),seLease(101,7)},Saved[2];memcpy(Saved,Reuse,sizeof(Reuse));testRequire(xcronExecutorSubmitBatchSelected(B,Reuse,2,NULL),"reuse both batch slots before earlier Notify tails finish");memset(Reuse,0xa5,sizeof(Reuse));xrtAtomic32Store(&C.NotifyGate,1,XMEMORY_RELEASE);seBatchReceipts(B,Saved,2,false);seEnd(B);sePoolEnd(E);

    E=sePool(4,128);C=(selectedexeccontext){0};B=seAdapter(E,64,&C,false);testRequire(xcronExecutorSubmitBatchSelected(B,Runs,64,NULL),"warm selected batch");seBatchReceipts(B,Runs,64,false);xallocationbudget* Budget=NULL;xallocationscope Scope={0};testRequire(xrtAllocationBudgetCreate(1,&Budget),"selected batch warmed budget");xrtSetErrorInfo(XERR_STATE,"selected.batch.owner",23,"retain ambient error");const xerror* Ambient=xrtGetError();testRequire(xrtAllocationBudgetEnter(Budget,&Scope),"selected batch no requested heap quota");
#if defined(XRT_FEATURE_MEMORY_STATS)
    xmemstats Before,After;xrtMemStatsEnable(true);xrtMemStatsGet(&Before);
#endif
    for(unsigned Round=0;Round<512;++Round){for(unsigned J=0;J<64;++J)Runs[J]=seLease((uint64)Round*64+J+65,7);testRequire(xcronExecutorSubmitBatchSelected(B,Runs,64,NULL),"selected maximum zero-heap batch");seBatchReceipts(B,Runs,64,false);testRequire(xrtGetError()==Ambient,"selected batch preserves owner ambient error");}
#if defined(XRT_FEATURE_MEMORY_STATS)
    xrtMemStatsGet(&After);xrtMemStatsEnable(false);testRequire(Before.MallocCalls==After.MallocCalls && Before.CallocCalls==After.CallocCalls && Before.ReallocCalls==After.ReallocCalls && Before.BlockAllocCalls==After.BlockAllocCalls,"selected batch submission/labels/physical receipts request no heap");
#endif
    testRequire(!Scope.Rejections && xrtAllocationBudgetLeave(&Scope),"selected batch warm scope rejected nothing");xrtClearError();xrtAllocationBudgetFree(Budget);seEnd(B);sePoolEnd(E);
}
